from pathlib import Path
from functools import wraps
import hashlib

from PIL import Image

try:
    CACHE_DIR = Path(__file__).resolve().parent.parent.parent / "nbs" / ".cache"
except NameError:
    # __file__ is not defined in Jupyter notebooks — use cwd
    CACHE_DIR = Path(".cache")
CACHE_DIR.mkdir(parents=True, exist_ok=True)


def _hash_arg(arg) -> bytes:
    """Return bytes that uniquely represent an argument for cache keying."""
    if isinstance(arg, Image.Image):
        return arg.tobytes()
    return repr(arg).encode()


def image_cache(fn):
    """Decorator for functions that return a PIL Image.

    Adds a `cached: bool = False` kwarg. When True, loads the last saved
    result from .cache/<fn_name>_<args_hash>.png instead of calling the function.
    Every successful call saves its result to cache regardless.

    Cache key = md5 hash of all args/kwargs. Different inputs get different entries.
    PIL Images are hashed by pixel data, everything else by repr().
    """
    @wraps(fn)
    def wrapper(*args, cached: bool = False, **kwargs) -> Image.Image:
        h = hashlib.md5()
        for a in args:
            h.update(_hash_arg(a))
        for k in sorted(kwargs):
            h.update(k.encode())
            h.update(_hash_arg(kwargs[k]))
        key = f"{fn.__name__}_{h.hexdigest()[:12]}"
        path = CACHE_DIR / f"{key}.png"
        if cached and path.exists():
            return Image.open(path)  # preserve original mode (RGB or RGBA)
        img = fn(*args, **kwargs)
        img.save(path)
        return img
    return wrapper


